SELECT
,
member_level.level_name AS levelName
FROM
user_info AS user_info
LEFT JOIN member_level AS member_level ON user_info.member_level_id = member_level.id AND member_level.del_flag = '0'

    user_info.del_flag = '0'

        AND user_info.`phone` = #{query.phone}


        AND user_info.`sex` = #{query.sex}


        AND user_info.`user_source` = #{query.userSource}


        AND user_info.`member_level_id` = #{query.memberLevelId}


ORDER BY user_info.create_time DESC
